"""Write every supplementary table (CSV in results/tables/ and one Markdown file in docs/SUPPLEMENTARY_TABLES.md) from the result JSON files."""
import json, os
import numpy as np, pandas as pd
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..')); RES = os.path.join(ROOT, 'results'); TAB = os.path.join(RES, 'tables'); DOC = os.path.join(ROOT, 'docs'); DATA = os.path.join(ROOT, 'data', 'derived')
os.makedirs(TAB, exist_ok=True)
E = json.load(open(f'{RES}/detect_transfer.json')); X = json.load(open(f'{RES}/extra_analyses.json')); FJ = json.load(open(f'{RES}/feasibility_localisation.json')); F = json.load(open(f'{RES}/facts.json')); AR = json.load(open(f'{DATA}/ppgen_audit_report.json'))
md = ['# Supplementary tables\n', 'All tables are generated by `src/make_supplementary_tables.py` from the JSON files in `results/`. CSV versions are in `results/tables/`.\n']
def put(name, title, df, note=''):
    df.to_csv(f'{TAB}/{name}.csv', index=False); md.append(f'\n## {title}\n'); 
    if note: md.append(note + '\n')
    md.append(df.to_markdown(index=False, floatfmt='.3f') + '\n')
# S1 Brazil audit per file
rows = []
for k, v in AR['files'].items():
    rows.append(dict(condition=k.replace('_csv', ''), rows=v['rows'], rows_per_cycle=v['rows_per_cycle_consistent_with'], cycles=v['cycles'], nan_total=sum(v['nan'].values()), V_min=v['ranges']['V'][0], V_max=v['ranges']['V'][1], I_min=v['ranges']['I'][0], I_max=v['ranges']['I'][1],
                     G_min=v['ranges']['G'][0], G_max=v['ranges']['G'][1], T_min=v['ranges']['T'][0], T_max=v['ranges']['T'][1], G_constant_in_window_share=v['G_const_in_window_share'], T_constant_in_window_share=v['T_const_in_window_share']))
put('S1_ppgen_audit_per_file', 'S1. PPGEN-SILVA2020: audit of the 20 files', pd.DataFrame(rows), 'Window length is inferred from the row count (all files are divisible by 9,996, not 9,960). The file `08_Partial_shading_Panel2` has windows with G = 0 and T = 0 (invalid, removed).')
# S2 Réunion QC
put('S2_reunion_qc_log', 'S2. La Réunion: sequential quality control (hours retained)', pd.read_csv(f'{RES}/reunion_qc_log.csv'))
# S3 within-site, S4 cross-site
def flat(d, site):
    return pd.DataFrame([dict(setting=site, model=k.split(' | ')[0], features=k.split(' | ')[1], AUC=v['auc'], AUC_CI_low=v['auc_ci'][0], AUC_CI_high=v['auc_ci'][1], average_precision=v['ap'], positive_prevalence=v['prev'], balanced_accuracy_at_0_5=v['bal']) for k, v in d.items()])
put('S3_within_site', 'S3. Within-site detection (all models and feature sets)', pd.concat([flat(E['A_within_brazil'], 'Brazil (cycle-blocked chronological)'), flat(E['B_within_reunion'], 'Réunion (leave-fault-day-out)')]))
put('S4_cross_site', 'S4. Cross-site detection (all models and feature sets)', pd.concat([flat(E['C_brazil_to_reunion'], 'Brazil -> Réunion'), flat(E['D_reunion_to_brazil'], 'Réunion -> Brazil')]))
# S5 paired
P = X['paired_holm']; put('S5_paired_comparisons', 'S5. Paired AUC differences with Holm correction (six exploratory comparisons)', pd.DataFrame([dict(comparison=k, delta_AUC=v['diff'], CI_low=v['ci'][0], CI_high=v['ci'][1], p=v['p'], p_holm=v['p_holm']) for k, v in P.items()]))
# S6 signatures + severity
put('S6_feature_signatures', 'S6. Median normalised features by condition', pd.DataFrame([dict(condition=k, n=v['n'], median_loss=v['loss'], median_Vrel=v['Vrel'], median_Irel=v['Irel']) for k, v in F['signature'].items()]))
sv = X['severity_loss_auc']; put('S7_severity', 'S7. Severity: full vs partial shading (Brazil), relative loss alone', pd.DataFrame([dict(AUC=sv['auc'], CI_low=sv['ci'][0], CI_high=sv['ci'][1], median_loss_full=sv['median_loss_full'], median_loss_partial=sv['median_loss_partial'], n_full=sv['n_full'], n_partial=sv['n_partial'])]))
# S8 localisation + phase-1 feasibility
rows = []
for key in ('5class_all', '3class_shading', 'binary_shading', 'loc_full', 'loc_partial'):
    for fs, r in FJ[key]['results'].items(): rows.append(dict(task=key, features=fs, chance=FJ[key]['chance'], n_train=FJ[key]['n_train'], n_test=FJ[key]['n_test'], logreg_balanced_acc=r['logreg']['bal_acc'], xgb_balanced_acc=r['xgb']['bal_acc'], xgb_macro_F1=r['xgb']['macro_f1']))
put('S8_window_level_feasibility', 'S8. Window-level classification and panel localisation (Phase-1 feasibility)', pd.DataFrame(rows), 'Chronological split by cycle (first 70% train, last 30% test). Panel localisation is at chance for every feature set.')
# S9 robustness
rob = E['G_robustness_brazil_auc']; put('S9_robustness', 'S9. Robustness within Brazil (XGBoost AUC, models not retrained)', pd.DataFrame([dict(perturbation=k.split('_')[0], level=float(k.split('_')[1]), **v) for k, v in rob.items()]))
# S10 cost and SHAP
c = X['cost']; put('S10_model_cost', 'S10. Model size and cost (timings depend on the machine)', pd.DataFrame([dict(model=k, params_or_tree_nodes=v['params_or_nodes'], train_seconds=v['train_s'], inference_us_per_sample=v['infer_us_per_sample']) for k, v in c.items()]))
put('S11_shap', 'S11. Mean |SHAP| of the XGBoost detector within Brazil', pd.DataFrame([dict(feature=k, mean_abs_shap=v) for k, v in E['F_mean_abs_shap_brazil'].items()]))
open(f'{DOC}/SUPPLEMENTARY_TABLES.md', 'w', encoding='utf8').write('\n'.join(md)); print('tables written:', len(os.listdir(TAB)))
